"""Fat Dog Takeover toe: every image on every page becomes the Fat Dog.

A port of the Fat Dog Takeover browser extension to a FeetBrowser toe. The
original swaps every image -- <img> tags, SVG images, video posters, CSS
backgrounds -- for the iconic Fat Dog, stretched to fill whatever shape the
original occupied (object-fit: fill).

FeetBrowser draws each image at its real displayed size, so this toe takes
the one approach that keeps the page layout untouched: it leaves the HTML
alone and, on every repaint, paints the Fat Dog stretched over each image's
canvas box. A banner stays a banner, a circle stays a circle; it is just
all Fat Dog now.

The dog is bundled inside this single file as base64 (the original
fat_dog.png, unmodified). It is decoded with FeetBrowser's own image
decoder (canvas.PhotoImage -> feetbrowser_engine.decode_png) and stretched
with the engine's own raster resize (imagecodec.resize): the toe writes no
image decoding or scaling code of its own. Resized copies are cached per
unique box size, so the per-frame cost is drawing, not rescaling.

Toolbar button "DOG" toggles the takeover on/off; the ToeHub config page
(toehub://config/fat-dog-takeover) picks the stretch mode and a minimum
box area to leave tiny icons alone.
"""

from feetbrowser import toes
from feetbrowser.canvas import PhotoImage, CanvasError
from feetbrowser import imagecodec

