# Module-level mirrors of the config so on_draw (which gets no ctx) can read
# them, exactly like the dark-mode toe. _BASE is decoded lazily; _CACHE holds
# the resized dogs so a repaint never resizes anything.
_ENABLED = [True]
_FIT = ["fill"]
_MIN_PX = [0]
_BASE = [None]
_CACHE = {}
_CACHE_LIMIT = 512


def activate(ctx):
    ctx.define_config(
        toes.ConfigOption("enabled", "Fat Dog active", "bool", default=True,
                          help="Replace every image with the Fat Dog."),
        toes.ConfigOption("fit", "Stretch mode", "choice", default="fill",
                          options=[("fill", "Fill (stretch)"),
                                   ("cover", "Cover (crop)"),
                                   ("contain", "Contain (fit inside)")],
                          help="How the dog fits the space the image occupied."),
        toes.ConfigOption("min_pixels", "Skip smaller than", "int", default=0,
                          help="Leave images smaller than this many pixels\u00b2 "
                               "alone (0 replaces everything)."),
    )
    _sync_config(ctx)
    ctx.on("buttons", lambda: [toes.ButtonDef("fatdog", "DOG",
                                              "Fat Dog Takeover")])
    ctx.on("on_click", lambda btn_id: _toggle(ctx, btn_id))
    ctx.on("on_draw", lambda canvas, offset: _overlay(ctx, canvas, offset))


def _sync_config(ctx):
    """Copy declared config values to the module mirrors on_draw can read."""
    for key, opt in ctx.config_options():
        if key == "enabled":
            _ENABLED[0] = ctx.config_value("enabled")
        elif key == "fit":
            _FIT[0] = ctx.config_value("fit")
        elif key == "min_pixels":
            _MIN_PX[0] = int(ctx.config_value("min_pixels") or 0)


def _toggle(ctx, btn_id):
    if btn_id != "fatdog":
        return
    _ENABLED[0] = not _ENABLED[0]
    ctx.set_config("enabled", _ENABLED[0])
    ctx.set_status("Fat Dog Takeover is ON." if _ENABLED[0]
                   else "Fat Dog Takeover is OFF. The dog rests.")
    tab = ctx.current_tab()
    if tab and tab.url and not str(tab.url).startswith(("toe://", "toehub://")):
        tab.load(tab.url, push=False)


def _overlay(ctx, canvas, offset):
    """Paint the Fat Dog stretched over every image item on the canvas.

    Re-syncs the config mirrors each frame: the ToeHub config page changes
    settings through ctx.set_config without calling the toe back, so reading
    them here (a few lookups) is what makes a new stretch mode or a disable
    take effect on the next repaint.
    """
    _sync_config(ctx)
    if not _ENABLED[0]:
        return
    if _BASE[0] is None and not _ensure_base():
        return
    items = getattr(canvas, "_items", None)
    if not items:
        return
    fit = _FIT[0]
    min_px = _MIN_PX[0]
    for item in items:
        if item.kind != "image" or "page" not in item.tags:
            continue
        photo = item.opts.get("image")
        if photo is None or len(item.coords) < 2:
            continue
        bw = photo.width()
        bh = photo.height()
        if bw < 1 or bh < 1:
            continue
        if min_px and bw * bh < min_px:
            continue
        dog, ox, oy = _dog_for(bw, bh, fit)
        if dog is None:
            continue
        canvas.create_image(item.coords[0] + ox, item.coords[1] + oy,
                            anchor="nw", image=dog)


def _ensure_base():
    """Decode the bundled Fat Dog once, and only when it is needed, using
    FeetBrowser's own image decoder (PhotoImage -> imagecodec.decode)."""
    try:
        _BASE[0] = PhotoImage(data="".join(_FAT_DOG_B64.split()))
    except CanvasError:
        _BASE[0] = False
    return bool(_BASE[0])


def _dog_for(bw, bh, fit):
    """A Fat Dog PhotoImage sized for a `bw` x `bh` box, plus draw offsets.

    `fill` stretches to the exact box (the signature effect). `cover` scales
    up to cover the box, then crops to it. `contain` scales down to fit
    inside the box and is drawn centered, leaving the original visible in
    the letterbox. Results are cached per (size, fit).
    """
    key = (int(round(bw)), int(round(bh)), fit)
    cached = _CACHE.get(key)
    if cached is not None:
        return cached
    base = _BASE[0]
    sw, sh = base.width(), base.height()
    if fit == "cover":
        scale = max(bw / sw, bh / sh)
        dw, dh = int(round(sw * scale)), int(round(sh * scale))
        dog = _resize(base, dw, dh)
        ox, oy = (bw - dw) // 2, (bh - dh) // 2
        dog = _crop(dog, bw, bh)
        ox, oy = 0, 0
    elif fit == "contain":
        scale = min(bw / sw, bh / sh)
        dw, dh = max(1, int(round(sw * scale))), max(1, int(round(sh * scale)))
        dog = _resize(base, dw, dh)
        ox, oy = (bw - dw) // 2, (bh - dh) // 2
    else:  # fill
        dog = _resize(base, max(1, int(round(bw))), max(1, int(round(bh))))
        ox, oy = 0, 0
    if dog is None:
        return None, 0, 0
    if len(_CACHE) >= _CACHE_LIMIT:
        _CACHE.pop(next(iter(_CACHE)))
    _CACHE[key] = (dog, ox, oy)
    return dog, ox, oy


def _resize(photo, w, h):
    """A new PhotoImage resized to `w` x `h` via the engine's raster resize
    (imagecodec.resize), not a custom scaler."""
    try:
        rgba = imagecodec.resize(photo.rgba, photo.width(), photo.height(),
                                 w, h)
    except Exception:  # noqa: BLE001 - a bad size should never break a frame
        return None
    clone = PhotoImage(width=w, height=h)
    clone.rgba = bytearray(rgba)
    clone.opaque = photo.opaque
    return clone


def _crop(photo, w, h):
    """The centered `w` x `h` region of an already-decoded photo.

    Cropping decoded pixels is not decoding; it just trims a bytearray to
    the box that `cover` needs visible.
    """
    sw, sh = photo.width(), photo.height()
    x0 = max(0, (sw - w) // 2)
    y0 = max(0, (sh - h) // 2)
    x1 = min(sw, x0 + w)
    y1 = min(sh, y0 + h)
    w, h = x1 - x0, y1 - y0
    if w < 1 or h < 1:
        return None
    rows = []
    for y in range(y0, y1):
        start = (y * sw + x0) * 4
        rows.append(bytes(photo.rgba[start:start + w * 4]))
    clone = PhotoImage(width=w, height=h)
    clone.rgba = bytearray(b"".join(rows))
    clone.opaque = photo.opaque
    return clone
